body.tpl-lite { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 10.5px; color: #1e293b; margin: 0; padding: 15px; background-color: #ffffff; }
.tpl-lite .header-table { width: 100%; background-color: {{ $accentColor ? $accentColor.'0A' : '#f0f9ff' }}; border: 1px solid {{ $accentColor ? $accentColor.'26' : '#bae6fd' }}; border-radius: 6px; padding: 10px 14px; margin-bottom: 15px; }
.tpl-lite .company-name { font-size: 16px; font-weight: bold; color: {{ $accentColor ?: '#0284c7' }}; }
.tpl-lite .company-address { font-size: 9px; color: #64748b; }
.tpl-lite .payslip-title { font-size: 16px; font-weight: bold; color: {{ $accentColor ?: '#0284c7' }}; text-align: right; }
.tpl-lite .employee-info-table { width: 100%; background-color: #ffffff; border: 1px solid #f1f5f9; border-collapse: collapse; margin-bottom: 15px; }
.tpl-lite .employee-info-table td { padding: 5px 8px; font-size: 10px; border-bottom: 1px solid #f8fafc; }
.tpl-lite .meta-label { color: #64748b; font-weight: 500; }
.tpl-lite .meta-val { font-weight: bold; color: #0f172a; }
.tpl-lite .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-lite .components-table th { background-color: {{ $accentColor ? $accentColor.'14' : '#e0f2fe' }}; color: {{ $accentColor ?: '#0369a1' }}; border-bottom: 1px solid {{ $accentColor ? $accentColor.'33' : '#7dd3fc' }}; padding: 6px 8px; font-size: 9.5px; text-transform: uppercase; font-weight: bold; }
.tpl-lite .components-table td { border-bottom: 1px solid #f1f5f9; padding: 5px 8px; font-size: 9.5px; }
.tpl-lite .net-pay-box { background-color: {{ $accentColor ? $accentColor.'0F' : '#f0f9ff' }}; border: 1px solid {{ $accentColor ? $accentColor.'33' : '#bae6fd' }}; color: {{ $accentColor ?: '#0369a1' }}; padding: 8px 14px; margin-bottom: 15px; border-radius: 6px; }
.tpl-lite .net-amount { font-size: 14px; font-weight: bold; color: {{ $accentColor ?: '#0284c7' }}; }
.tpl-lite .net-words { font-size: 9px; font-style: italic; text-align: right; color: {{ $accentColor ?: '#0369a1' }}; }
.tpl-lite .footer-note { text-align: center; font-size: 8.5px; color: #94a3b8; margin-top: 15px; }
